        A.doors.push({ id: did, at: at, w: doorW, to: B.id, swing: 'out', hinge: 'left', leaf: false });
        B.doors.push({ id: did, at: at, w: doorW, to: A.id, swing: 'in', hinge: 'left' });
        cut.door = { id: did, s: made.s, w: doorW };
