      id: id, culture: shell.culture || null, wealth: shell.wealth == null ? 0.5 : shell.wealth, y: levels[0].y,
      frame: { O: [R3(O[0]), R3(O[1])], U: [R3(U[0], 6), R3(U[1], 6)], V: [R3(V[0], 6), R3(V[1], 6)] },
